changeSet.sql:
ALTER TABLE tc_game_session_members ADD CONSTRAINT ck_gm_members_role
  CHECK (role IN ('player', 'supporter', 'hunter', 'spectator'));
ALTER TABLE tc_game_session_members ADD CONSTRAINT ck_gm_members_number
  CHECK (number >= 1 AND (role <> 'spectator' OR number = 1));
ALTER TABLE tc_game_session_members ADD CONSTRAINT ck_gm_members_state
  CHECK ((state = 'active' AND retiredat IS NULL) OR (state = 'retired' AND retiredat IS NOT NULL));

ALTER TABLE tc_game_mirrors ADD CONSTRAINT ck_gm_mirrors_destination
  CHECK ((destinationrole IS NOT NULL AND destinationrole IN ('player', 'supporter', 'hunter')
      AND destinationmemberid IS NULL)
    OR (destinationrole IS NULL AND destinationmemberid IS NOT NULL));
ALTER TABLE tc_game_mirrors ADD CONSTRAINT ck_gm_mirrors_state CHECK (state IN ('active', 'retiring'));
ALTER TABLE tc_game_session_groups ADD CONSTRAINT ck_gm_groups_state CHECK (state IN ('active', 'retiring'));
ALTER TABLE tc_game_session_geofences ADD CONSTRAINT ck_gm_geofences_state
  CHECK (state IN ('active', 'retiring'));

ALTER TABLE tc_game_timetable_entries ADD CONSTRAINT ck_gm_entries_status
  CHECK (status IN ('scheduled', 'sent', 'skipped', 'failed'));

ALTER TABLE tc_game_requests ADD CONSTRAINT ck_gm_requests_status
  CHECK (status IN ('pending', 'approved', 'executing', 'succeeded', 'failed', 'rejected', 'expired',
    'cancelled'));

ALTER TABLE tc_game_jokers ADD CONSTRAINT ck_gm_jokers_type
  CHECK (type IN ('hunterPositions', 'fakePing', 'break'));
ALTER TABLE tc_game_jokers ADD CONSTRAINT ck_gm_jokers_quantities CHECK (granted >= 0 AND used >= 0);
ALTER TABLE tc_game_joker_pools ADD CONSTRAINT ck_gm_joker_pools_type CHECK (type IN ('speedhunt'));
ALTER TABLE tc_game_joker_pools ADD CONSTRAINT ck_gm_joker_pools_quantities CHECK (granted >= 0 AND used >= 0);
ALTER TABLE tc_game_joker_reservations ADD CONSTRAINT ck_gm_reservations_owner
  CHECK ((type = 'speedhunt' AND memberid IS NULL)
    OR (type IN ('hunterPositions', 'fakePing', 'break') AND memberid IS NOT NULL));
ALTER TABLE tc_game_joker_reservations ADD CONSTRAINT ck_gm_reservations_status
  CHECK (status IN ('reserved', 'consumed', 'released'));
ALTER TABLE tc_game_joker_ledger ADD CONSTRAINT ck_gm_ledger_owner
  CHECK ((type = 'speedhunt' AND memberid IS NULL)
    OR (type IN ('hunterPositions', 'fakePing', 'break') AND memberid IS NOT NULL));

ALTER TABLE tc_game_catches ADD CONSTRAINT ck_gm_catches_active
  CHECK ((releasedat IS NULL AND activememberid IS NOT NULL AND activememberid = memberid)
    OR (releasedat IS NOT NULL AND activememberid IS NULL AND releasedat >= caughtat));

ALTER TABLE tc_game_speedhunts ADD CONSTRAINT ck_gm_speedhunts_active
  CHECK ((endedat IS NULL AND outcome IS NULL AND activememberid IS NOT NULL
      AND activememberid = targetmemberid)
    OR (endedat IS NOT NULL AND outcome IS NOT NULL AND outcome IN ('completed', 'terminated')
      AND activememberid IS NULL));

ALTER TABLE tc_game_fake_ping_plans ADD CONSTRAINT ck_gm_fake_plans_use
  CHECK ((timetableentryid IS NOT NULL AND pingnumber IS NULL AND boundrunid IS NULL
      AND unboundmemberid IS NULL AND (openentryid IS NULL OR openentryid = timetableentryid))
    OR (timetableentryid IS NULL AND pingnumber IS NOT NULL AND pingnumber >= 1 AND openentryid IS NULL
      AND (unboundmemberid IS NULL OR (unboundmemberid = memberid AND boundrunid IS NULL))));
ALTER TABLE tc_game_fake_ping_plans ADD CONSTRAINT ck_gm_fake_plans_position
  CHECK (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180);

ALTER TABLE tc_game_speedhunt_pings ADD CONSTRAINT ck_gm_pings_number CHECK (number >= 1);
ALTER TABLE tc_game_speedhunt_pings ADD CONSTRAINT ck_gm_pings_mode CHECK (mode IN ('static', 'live'));
ALTER TABLE tc_game_speedhunt_pings ADD CONSTRAINT ck_gm_pings_source
  CHECK ((source = 'jokerFake' AND fakeplanid IS NOT NULL)
    OR (source IN ('real', 'operatorFake') AND fakeplanid IS NULL));

ALTER TABLE tc_game_live_uploads ADD CONSTRAINT ck_gm_live_uploads_purpose
  CHECK ((purpose IN ('speedhuntPing', 'manual', 'geofenceAuto') AND sourcememberid IS NOT NULL
      AND recipientmemberid IS NULL AND (pingid IS NULL OR purpose = 'speedhuntPing'))
    OR (purpose = 'hunterRelay' AND sourcememberid IS NULL AND recipientmemberid IS NOT NULL
      AND pingid IS NULL));
ALTER TABLE tc_game_live_uploads ADD CONSTRAINT ck_gm_live_uploads_state
  CHECK ((state = 'active' AND endedat IS NULL) OR (state = 'ended' AND endedat IS NOT NULL));
ALTER TABLE tc_game_live_uploads ADD CONSTRAINT ck_gm_live_uploads_interval CHECK (intervalseconds >= 1);

ALTER TABLE tc_game_breaks ADD CONSTRAINT ck_gm_breaks_state
  CHECK ((state IN ('planned', 'waiting') AND plannedstart IS NOT NULL AND startedat IS NULL
      AND activememberid IS NULL)
    OR (state = 'active' AND startedat IS NOT NULL AND deadline IS NOT NULL AND endedat IS NULL
      AND activememberid IS NOT NULL AND activememberid = memberid)
    OR (state = 'ended' AND startedat IS NOT NULL AND deadline IS NOT NULL AND endedat IS NOT NULL
      AND activememberid IS NULL)
    OR (state IN ('cancelled', 'missed') AND startedat IS NULL AND endedat IS NOT NULL
      AND activememberid IS NULL));
ALTER TABLE tc_game_breaks ADD CONSTRAINT ck_gm_breaks_planned_by
  CHECK (plannedby IN ('participant', 'operator'));

ALTER TABLE tc_game_push_outbox ADD CONSTRAINT ck_gm_outbox_status
  CHECK (status IN ('queued', 'attempting', 'sent', 'failed', 'uncertain'));
